// Utility for playing simple synthesized sounds using Web Audio API

class AudioSynth {
  private ctx: AudioContext | null = null;
  musicEnabled: boolean = true;
  
  private html5Correct: HTMLAudioElement | null = null;
  private html5Badge: HTMLAudioElement | null = null;
  
  constructor() {
    if (typeof window !== 'undefined') {
      this.html5Badge = new Audio('data:audio/wav;base64,');
      this.html5Badge.volume = 0.5;
    }
  }
  playHTML5Badge() {
    if (!this.musicEnabled || !this.html5Badge) return;
    this.html5Badge.currentTime = 0;
    this.html5Badge.play().catch(e => console.warn('HTML5 Audio Badge Error:', e));
  }

  setMusicPreference(enabled: boolean) {
    this.musicEnabled = enabled;
    if (!enabled) this.stopBackgroundMusic();
  }

  private getCtx() {
    if (!this.ctx) {
      this.ctx = new (window.AudioContext || (window as any).webkitAudioContext)();
    }
    if (this.ctx.state === 'suspended') {
      this.ctx.resume();
    }
    return this.ctx;
  }

  playTick() {
    if (!this.musicEnabled) return;
    try {
      const ctx = this.getCtx();
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.type = 'sine';
      osc.frequency.setValueAtTime(400, ctx.currentTime);
      osc.frequency.exponentialRampToValueAtTime(300, ctx.currentTime + 0.1);
      gain.gain.setValueAtTime(0.05, ctx.currentTime);
      gain.gain.exponentialRampToValueAtTime(0.01, ctx.currentTime + 0.1);
      osc.connect(gain);
      gain.connect(ctx.destination);
      osc.start();
      osc.stop(ctx.currentTime + 0.1);
    } catch (e) {
      console.warn("Audio play failed", e);
    }
  }

  playCorrect() {
    if (!this.musicEnabled) return;
    try {
      const ctx = this.getCtx();
      // A pleasant, realistic-sounding chime (major chord with rich harmonics)
      const playBell = (freq, time, duration, vol) => {
        const osc1 = ctx.createOscillator();
        const osc2 = ctx.createOscillator();
        const gain = ctx.createGain();
        
        osc1.type = 'sine';
        osc2.type = 'triangle';
        osc1.frequency.value = freq;
        osc2.frequency.value = freq * 2; // Octave above for brightness
        
        gain.gain.setValueAtTime(0, ctx.currentTime + time);
        gain.gain.linearRampToValueAtTime(vol, ctx.currentTime + time + 0.05);
        gain.gain.exponentialRampToValueAtTime(0.01, ctx.currentTime + time + duration);
        
        osc1.connect(gain);
        osc2.connect(gain);
        gain.connect(ctx.destination);
        
        osc1.start(ctx.currentTime + time);
        osc2.start(ctx.currentTime + time);
        osc1.stop(ctx.currentTime + time + duration);
        osc2.stop(ctx.currentTime + time + duration);
      };
      
      // Arpeggiate a C Major 7 chord rapidly
      playBell(523.25, 0, 0.4, 0.2);     // C5
      playBell(659.25, 0.05, 0.4, 0.15);  // E5
      playBell(783.99, 0.10, 0.4, 0.1);   // G5
      playBell(1046.50, 0.15, 0.8, 0.2);  // C6
    } catch (e) {
      console.warn("Audio play failed", e);
    }
  }

  playWrong() {
    if (!this.musicEnabled) return;
    try {
      const ctx = this.getCtx();
      // Realistic buzzer sound (two detuned sawtooth waves with lowpass filter sweep)
      const playBuzz = (freq, detune, duration, vol) => {
        const osc = ctx.createOscillator();
        const filter = ctx.createBiquadFilter();
        const gain = ctx.createGain();
        
        osc.type = 'sawtooth';
        osc.frequency.value = freq;
        osc.detune.value = detune;
        
        filter.type = 'lowpass';
        filter.frequency.setValueAtTime(2000, ctx.currentTime);
        filter.frequency.exponentialRampToValueAtTime(200, ctx.currentTime + duration);
        
        gain.gain.setValueAtTime(0, ctx.currentTime);
        gain.gain.linearRampToValueAtTime(vol, ctx.currentTime + 0.05);
        gain.gain.exponentialRampToValueAtTime(0.01, ctx.currentTime + duration);
        
        osc.connect(filter);
        filter.connect(gain);
        gain.connect(ctx.destination);
        
        osc.start(ctx.currentTime);
        osc.stop(ctx.currentTime + duration);
      };
      
      playBuzz(150, -10, 0.4, 0.15); // Low buzz
      playBuzz(150, 10, 0.4, 0.15);  // Detuned for thickness
      playBuzz(75, 0, 0.4, 0.1);   // Sub bass for impact
    } catch (e) {
      console.warn("Audio play failed", e);
    }
  }

  playCheer() {
    if (!this.musicEnabled) return;
    try {
      const ctx = this.getCtx();
      
      // 1. Triumphant Fanfare
      const playNote = (freq, timeOff, duration, vol = 0.2) => {
        const osc = ctx.createOscillator();
        const gain = ctx.createGain();
        osc.type = 'triangle';
        osc.frequency.setValueAtTime(freq, ctx.currentTime + timeOff);
        
        gain.gain.setValueAtTime(0, ctx.currentTime + timeOff);
        gain.gain.linearRampToValueAtTime(vol, ctx.currentTime + timeOff + 0.05);
        gain.gain.exponentialRampToValueAtTime(0.01, ctx.currentTime + timeOff + duration);
        
        osc.connect(gain);
        gain.connect(ctx.destination);
        
        osc.start(ctx.currentTime + timeOff);
        osc.stop(ctx.currentTime + timeOff + duration);
      };
      
      playNote(523.25, 0, 0.2); // C5
      playNote(659.25, 0.15, 0.2); // E5
      playNote(783.99, 0.3, 0.2); // G5
      playNote(1046.50, 0.45, 0.8, 0.3); // C6 longer and louder
      
      // 2. Crowd Cheer (White noise bursts filtered)
      const duration = 2.5;
      const bufferSize = ctx.sampleRate * duration;
      const buffer = ctx.createBuffer(1, bufferSize, ctx.sampleRate);
      const data = buffer.getChannelData(0);
      for (let i = 0; i < bufferSize; i++) {
        data[i] = Math.random() * 2 - 1; // White noise
      }
      
      const noiseSource = ctx.createBufferSource();
      noiseSource.buffer = buffer;
      
      const bandpass = ctx.createBiquadFilter();
      bandpass.type = 'bandpass';
      bandpass.frequency.setValueAtTime(1000, ctx.currentTime);
      bandpass.frequency.linearRampToValueAtTime(2000, ctx.currentTime + duration); // Sweeping up for excitement
      
      const noiseGain = ctx.createGain();
      noiseGain.gain.setValueAtTime(0, ctx.currentTime);
      noiseGain.gain.linearRampToValueAtTime(0.15, ctx.currentTime + 0.5); // Swell up
      noiseGain.gain.linearRampToValueAtTime(0.0, ctx.currentTime + duration); // Fade out
      
      noiseSource.connect(bandpass);
      bandpass.connect(noiseGain);
      noiseGain.connect(ctx.destination);
      
      noiseSource.start(ctx.currentTime);
      
    } catch (e) {
      console.warn("Audio play failed", e);
    }
  }
  
  playVictory() {
    this.playCheer();
  }

  playSwoosh() {
    if (!this.musicEnabled) return;
    try {
      const ctx = this.getCtx();
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.type = 'sine';
      osc.frequency.setValueAtTime(100, ctx.currentTime);
      osc.frequency.exponentialRampToValueAtTime(800, ctx.currentTime + 0.2);
      
      gain.gain.setValueAtTime(0.1, ctx.currentTime);
      gain.gain.linearRampToValueAtTime(0.0, ctx.currentTime + 0.2);
      
      osc.connect(gain);
      gain.connect(ctx.destination);
      osc.start();
      osc.stop(ctx.currentTime + 0.2);
    } catch (e) {
      console.warn("Audio play failed", e);
    }
  }
  
  playIntroMusic() {
    if (!this.musicEnabled) return;
    try {
      const ctx = this.getCtx();
      const playNote = (freq: number, timeOff: number, duration: number) => {
        const osc = ctx.createOscillator();
        const gain = ctx.createGain();
        osc.type = 'triangle';
        osc.frequency.value = freq;
        gain.gain.setValueAtTime(0.1, ctx.currentTime + timeOff);
        gain.gain.exponentialRampToValueAtTime(0.01, ctx.currentTime + timeOff + duration);
        osc.connect(gain);
        gain.connect(ctx.destination);
        osc.start(ctx.currentTime + timeOff);
        osc.stop(ctx.currentTime + timeOff + duration);
      };

      playNote(440, 0, 0.3);
      playNote(554.37, 0.2, 0.3);
      playNote(659.25, 0.4, 0.3);
      playNote(880, 0.6, 0.8);
    } catch (e) {
      console.warn("Audio play failed", e);
    }
  }

  private bgmInterval: NodeJS.Timeout | null = null;
  private bgmOscillators: OscillatorNode[] = [];
  private bgmGains: GainNode[] = [];

  startBackgroundMusic() {
    if (!this.musicEnabled) return;
    this.stopBackgroundMusic();
    try {
      const ctx = this.getCtx();
      let step = 0;
      // Vibrant, energetic sequence (C minor pentatonic arpeggios)
      const sequence = [
        261.63, 311.13, 392.00, 466.16, // C4, Eb4, G4, Bb4
        392.00, 311.13, 261.63, 196.00, // G4, Eb4, C4, G3
        261.63, 392.00, 523.25, 392.00, // C4, G4, C5, G4
        311.13, 261.63, 311.13, 392.00  // Eb4, C4, Eb4, G4
      ];
      
      this.bgmInterval = setInterval(() => {
        if (ctx.state === 'suspended') return;
        const osc = ctx.createOscillator();
        const gain = ctx.createGain();
        const filter = ctx.createBiquadFilter();
        
        osc.type = 'sawtooth';
        osc.frequency.setValueAtTime(sequence[step % sequence.length], ctx.currentTime);
        
        filter.type = 'lowpass';
        filter.frequency.setValueAtTime(2500, ctx.currentTime);
        filter.frequency.exponentialRampToValueAtTime(300, ctx.currentTime + 0.15);
        
        gain.gain.setValueAtTime(0, ctx.currentTime);
        gain.gain.linearRampToValueAtTime(0.08, ctx.currentTime + 0.02);
        gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.15);
        
        osc.connect(filter);
        filter.connect(gain);
        gain.connect(ctx.destination);
        
        osc.start(ctx.currentTime);
        osc.stop(ctx.currentTime + 0.15);
        
        this.bgmOscillators.push(osc);
        this.bgmGains.push(gain);
        
        // Cleanup old nodes
        if (this.bgmOscillators.length > 20) {
          this.bgmOscillators.shift();
          this.bgmGains.shift();
        }
        
        step++;
      }, 150); // Fast 150ms step
    } catch (e) {
      console.warn("Audio bgm start failed", e);
    }
  }

  startCombatMusic() {
    if (!this.musicEnabled) return;
    this.stopBackgroundMusic();
    try {
      const ctx = this.getCtx();
      let step = 0;
      // More intense, driving sequence for combat mode (D minor)
      const sequence = [
        146.83, 146.83, 174.61, 146.83, // D3, D3, F3, D3
        196.00, 174.61, 146.83, 130.81, // G3, F3, D3, C3
        146.83, 146.83, 220.00, 196.00, // D3, D3, A3, G3
        174.61, 146.83, 130.81, 146.83  // F3, D3, C3, D3
      ];
      
      this.bgmInterval = setInterval(() => {
        if (ctx.state === 'suspended') return;
        const osc = ctx.createOscillator();
        const gain = ctx.createGain();
        const filter = ctx.createBiquadFilter();
        
        osc.type = 'square'; // harsher tone
        osc.frequency.setValueAtTime(sequence[step % sequence.length], ctx.currentTime);
        
        filter.type = 'lowpass';
        filter.frequency.setValueAtTime(3000, ctx.currentTime);
        filter.frequency.exponentialRampToValueAtTime(200, ctx.currentTime + 0.12);
        
        gain.gain.setValueAtTime(0, ctx.currentTime);
        gain.gain.linearRampToValueAtTime(0.12, ctx.currentTime + 0.01);
        gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.12);
        
        osc.connect(filter);
        filter.connect(gain);
        gain.connect(ctx.destination);
        
        osc.start(ctx.currentTime);
        osc.stop(ctx.currentTime + 0.12);
        
        this.bgmOscillators.push(osc);
        this.bgmGains.push(gain);
        
        // Cleanup old nodes
        if (this.bgmOscillators.length > 20) {
          this.bgmOscillators.shift();
          this.bgmGains.shift();
        }
        
        step++;
      }, 130); // Faster 130ms step
    } catch (e) {
      console.warn("Audio bgm start failed", e);
    }
  }

  stopBackgroundMusic() {
    if (this.bgmInterval) {
      clearInterval(this.bgmInterval);
      this.bgmInterval = null;
    }
    this.bgmOscillators.forEach(osc => {
      try { osc.stop(); } catch(e) {}
    });
    this.bgmGains.forEach(gain => {
      try { gain.disconnect(); } catch(e) {}
    });
    this.bgmOscillators = [];
    this.bgmGains = [];
  }

  voicePreference: 'male' | 'female' | 'none' = 'female';

  setVoicePreference(pref: 'male' | 'female' | 'none') {
    this.voicePreference = pref;
  }

  speak(text: string, onEnd?: () => void) {
    if (this.voicePreference === 'none') {
      if (onEnd) {
        const delayMs = Math.max(1000, (text.length / 15) * 1000);
        setTimeout(onEnd, delayMs);
      }
      return;
    }

    if ('speechSynthesis' in window) {
      window.speechSynthesis.cancel(); // Cancel any ongoing speech
      
      // To add more expression and natural pauses, we can slightly process the text
      // For instance, adding commas or full stops naturally forces the Web Speech API to pause.
      let expressiveText = text.replace(/([.!?])\s*/g, '$1  '); // add extra space after punctuation for natural pause
      
      const utterance = new SpeechSynthesisUtterance(expressiveText);
      
      if (onEnd) {
        utterance.onend = onEnd;
      }
      
      // Try to find a good voice based on preference
      const voices = window.speechSynthesis.getVoices();
      let selectedVoice;
      
      if (this.voicePreference === 'female') {
        // Prioritize premium/natural voices (like Google US English, Microsoft Zira, etc.)
        selectedVoice = voices.find(v => v.name === 'Google US English') ||
                        voices.find(v => v.name.includes('Premium') && v.name.includes('Female')) ||
                        voices.find(v => v.name.includes('Natural') && v.name.includes('Female')) ||
                        voices.find(v => 
          v.name.includes('Female') || 
          v.name.includes('Samantha') || 
          v.name.includes('Victoria') ||
          v.name.includes('Karen') ||
          v.name.includes('Moira') ||
          (v.name.includes('Google') && v.name.includes('UK English'))
        ) || voices.find(v => v.lang.startsWith('en-') && !v.name.includes('Male'));
      } else if (this.voicePreference === 'male') {
        selectedVoice = voices.find(v => 
          v.name.includes('Male') || 
          v.name.includes('Alex') || 
          v.name.includes('Daniel') ||
          v.name.includes('David') ||
          (v.name.includes('Google') && v.name.includes('US English'))
        ) || voices.find(v => v.lang.startsWith('en-') && !v.name.includes('Female') && v.name.includes('Male'));
      }
      
      if (selectedVoice) {
        utterance.voice = selectedVoice;
      }
      
      // Fine-tuning for a more human-like expressive delivery
      utterance.rate = 0.92; // Slightly slower for better articulation and expressiveness
      if (this.voicePreference === 'female') {
        utterance.pitch = 1.15; // Slightly higher pitch for a more enthusiastic/expressive female tone
      } else {
        utterance.pitch = 1.0; 
      }
      
      window.speechSynthesis.speak(utterance);
    }
  }
}

export const audioSynth = new AudioSynth();
